@'
import fs from "node:fs";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";

const catalog = Object.freeze({ ACME: 101.25, BETA: 88.5 });

export function assess(raw, expectedCallId) {
  let envelope;
  try { envelope = typeof raw === "string" ? JSON.parse(raw) : raw; }
  catch { return { ok: false, reason: "malformed-json" }; }
  const response = envelope?.assistant_response;
  if (response?.stop_reason === "max_tokens") return { ok: false, reason: "incomplete" };
  const call = response?.content?.[0];
  if (call?.type !== "tool_use") return { ok: false, reason: "not-tool-use" };
  if (!call.input || typeof call.input !== "object") return { ok: false, reason: "bad-input" };
  if (typeof call.input.symbol !== "string") return { ok: false, reason: "bad-symbol-type" };
  return { ok: true, symbol: call.input.symbol, price: catalog[call.input.symbol] ?? null };
}

function cliFailure(reason, detail) {
  console.log(JSON.stringify({ ok: false, reason, ...(detail ? { detail } : {}) }));
  process.exitCode = 2;
}

function runCli() {
  const [file, caseName, expectedCallId] = process.argv.slice(2);
  if (!file || !caseName || !expectedCallId) return cliFailure("cli-usage");
  let cases;
  try { cases = JSON.parse(fs.readFileSync(file, "utf8")); }
  catch { return cliFailure("input-file-or-json"); }
  if (!cases || typeof cases !== "object" || Array.isArray(cases) || !Object.hasOwn(cases, caseName)) {
    return cliFailure("unknown-case", caseName);
  }
  const result = assess(cases[caseName], expectedCallId);
  console.log(JSON.stringify(result));
  process.exitCode = result.ok ? 0 : 1;
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) runCli();
