@'
import fs from "node:fs";
import os from "node:os";
import { resolve } from "node:path";
import { spawnSync } from "node:child_process";
import { isDeepStrictEqual } from "node:util";

const target = resolve(process.argv[2] ?? "learner.mjs");
const call = (id, name, input) => ({
  assistant_response: {
    role: "assistant",
    stop_reason: "tool_use",
    content: [{ type: "tool_use", id, name, input }]
  },
  result_receipt: { type: "tool_result", tool_use_id: id }
});
const cases = Object.freeze([
  ["valid", call("toolu-1", "lookup_stock", { symbol: "ACME" }), "toolu-1", 0,
    { ok:true, callId:"toolu-1", symbol:"ACME", price:101.25, currency:"USD", source:"offline-fixture", sideEffects:false, correlated:true }],
  ["wrong-type", call("toolu-2", "lookup_stock", { symbol: 42 }), "toolu-2", 1,
    { ok:false, reason:"bad-symbol-type" }],
  ["additional-key", call("toolu-3", "lookup_stock", { symbol:"ACME", limit:1 }), "toolu-3", 1,
    { ok:false, reason:"additional-key" }],
  ["null-input", call("toolu-4", "lookup_stock", null), "toolu-4", 1,
    { ok:false, reason:"bad-input" }],
  ["array-input", call("toolu-5", "lookup_stock", []), "toolu-5", 1,
    { ok:false, reason:"bad-input" }],
  ["malformed-json", "{\"assistant_response\":", "toolu-6", 1,
    { ok:false, reason:"malformed-json" }],
  ["domain-violation", call("toolu-7", "lookup_stock", { symbol:"TOOLONG" }), "toolu-7", 1,
    { ok:false, reason:"symbol-domain" }],
  ["unknown-tool", call("toolu-8", "delete_account", { symbol:"ACME" }), "toolu-8", 1,
    { ok:false, reason:"unknown-tool" }],
  ["wrong-correlation", {
    assistant_response:{ role:"assistant", stop_reason:"tool_use", content:[{ type:"tool_use", id:"toolu-9", name:"lookup_stock", input:{ symbol:"ACME" } }] },
    result_receipt:{ type:"tool_result", tool_use_id:"toolu-other" }
  }, "toolu-9", 1, { ok:false, reason:"wrong-correlation" }],
  ["refusal", {
    assistant_response:{ role:"assistant", stop_reason:"end_turn", content:[{ type:"refusal", refusal:"I cannot complete that request." }] },
    result_receipt:null
  }, "toolu-10", 1, { ok:false, reason:"refusal" }],
  ["completed-text", {
    assistant_response:{ role:"assistant", stop_reason:"end_turn", content:[{ type:"text", text:"The request is complete without a tool call." }] },
    result_receipt:null
  }, "toolu-11", 1, { ok:false, reason:"not-tool-use" }],
  ["incomplete", {
    assistant_response:{ role:"assistant", stop_reason:"max_tokens", content:[{ type:"text", text:"Partial" }] },
    result_receipt:null
  }, "toolu-12", 1, { ok:false, reason:"incomplete" }],
  ["changed-input", call("toolu-13", "lookup_stock", { symbol:"BETA" }), "toolu-13", 0,
    { ok:true, callId:"toolu-13", symbol:"BETA", price:88.5, currency:"USD", source:"offline-fixture", sideEffects:false, correlated:true }]
]);

const temp = fs.mkdtempSync(`${os.tmpdir()}${process.platform === "win32" ? "\\" : "/"}p42-tools-`);
const book = Object.fromEntries(cases.map(([name, value]) => [name, value]));
const bookPath = `${temp}${process.platform === "win32" ? "\\" : "/"}cases.json`;
fs.writeFileSync(bookPath, JSON.stringify(book), "utf8");
let failures = 0;
try {
  for (const [name, , expectedId, expectedExit, expectedResult] of cases) {
    const p = spawnSync(process.execPath, [target, bookPath, name, expectedId], { encoding:"utf8" });
    let actual;
    try { actual = JSON.parse(p.stdout.trim()); }
    catch { actual = { unparsable:true, stdout:p.stdout, stderr:p.stderr }; }
    const pass = p.status === expectedExit && isDeepStrictEqual(actual, expectedResult);
    console.log(`${pass ? "PASS" : "FAIL"} ${name}`);
    if (!pass) failures++;
  }
} finally {
  fs.rmSync(temp, { recursive:true, force:true });
}
console.log(`TOTAL ${cases.length} FAILED ${failures}`);
process.exitCode = failures ? 1 : 0;
