@'
import fs from "node:fs";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";

const prices = Object.freeze({ ACME:101.25, BETA:88.5 });
const permitted = new Set(["lookup_stock"]);

export function assess(raw, expectedCallId) {
  let e;
  try { e = typeof raw === "string" ? JSON.parse(raw) : raw; }
  catch { return { ok:false, reason:"malformed-json" }; }
  if (!e || typeof e !== "object" || Array.isArray(e)) return { ok:false, reason:"not-object" };
  const a = e.assistant_response;
  if (!a || typeof a !== "object" || Array.isArray(a)) return { ok:false, reason:"incomplete" };
  if (a.stop_reason === "max_tokens") return { ok:false, reason:"incomplete" };
  if (Array.isArray(a.content) && a.content.some(x => x?.type === "refusal")) {
    return { ok:false, reason:"refusal" };
  }
  if (a.stop_reason === "end_turn" && Array.isArray(a.content) && a.content.some(x => x?.type === "text")) {
    return { ok:false, reason:"not-tool-use" };
  }
  if (a.stop_reason !== "tool_use" || !Array.isArray(a.content) || a.content.length !== 1) {
    return { ok:false, reason:"incomplete" };
  }
  const c = a.content[0];
  if (!c || c.type !== "tool_use" || typeof c.id !== "string" || !c.id) return { ok:false, reason:"incomplete" };
  if (c.id !== expectedCallId) return { ok:false, reason:"wrong-correlation" };
  if (!permitted.has(c.name)) return { ok:false, reason:"unknown-tool" };
  if (!c.input || typeof c.input !== "object" || Array.isArray(c.input)) return { ok:false, reason:"bad-input" };
  const keys = Object.keys(c.input);
  if (keys.length !== 1 || keys[0] !== "symbol") return { ok:false, reason:"additional-key" };
  if (typeof c.input.symbol !== "string") return { ok:false, reason:"bad-symbol-type" };
  if (!/^[A-Z]{1,5}$/.test(c.input.symbol)) return { ok:false, reason:"symbol-domain" };
  if (!Object.hasOwn(prices, c.input.symbol)) return { ok:false, reason:"unauthorized-symbol" };
  const receipt = e.result_receipt;
  if (!receipt || receipt.type !== "tool_result" || receipt.tool_use_id !== expectedCallId || receipt.tool_use_id !== c.id) {
    return { ok:false, reason:"wrong-correlation" };
  }
  const price = prices[c.input.symbol];
  if (!Number.isFinite(price) || price < 0 || price > 1000000) return { ok:false, reason:"price-out-of-range" };
  return { ok:true, callId:c.id, symbol:c.input.symbol, price, currency:"USD", source:"offline-fixture", sideEffects:false, correlated:true };
}

function emitFailure(reason, detail) {
  console.log(JSON.stringify({ ok:false, reason, ...(detail ? { detail } : {}) }));
  process.exitCode = 2;
}
function runCli() {
  const [file, caseName, expectedCallId] = process.argv.slice(2);
  if (!file || !caseName || !expectedCallId) return emitFailure("cli-usage");
  let cases;
  try { cases = JSON.parse(fs.readFileSync(file, "utf8")); }
  catch { return emitFailure("input-file-or-json"); }
  if (!cases || typeof cases !== "object" || Array.isArray(cases) || !Object.hasOwn(cases, caseName)) {
    return emitFailure("unknown-case", caseName);
  }
  const result = assess(cases[caseName], expectedCallId);
  console.log(JSON.stringify(result));
  process.exitCode = result.ok ? 0 : 1;
}
if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) runCli();
